\label{th:1}
    Let $f:\mathbb R^p\to\mathbb R$ be $m$-strongly convex 
    and have $\Mmax$-Lipschitz gradient, with $0<m\leqslant 
    \Mmax$. Let $\bvartheta$ and $\bxi\sim \mathcal N(0,\mathbf 
    I_p)$ be two independent random vectors in $\mathbb R^p$. 
    If we denote by $\nu$ and $\nu^+$ the distributions of 
    $\bvartheta$ and $\bvartheta^+ =\bvartheta - h\nabla f 
    (\bvartheta) + \sqrt{2h}\,\bxi$, respectively, then for 
    every $h\geqslant 0$, we have
    \begin{align}
        \wass_2^2(\nu^+, \pi)  &\leqslant 
        \frac{1-mh}{1+mh}\,\wass_2^2(\nu, \pi) 
        + \frac{(\Mav+m)h^2p}{1+mh} + \frac{h^2(h\Mmax-1)}
        {1+mh}\|\nabla f(\bvartheta)\|_{
        \mathbb L_2}^2.\label{claim1}
    \end{align}
    The Langevin Monte Carlo algorithm with constant step-size
    $0\leqslant h\leqslant 1/\Mmax$ satisfies
    \begin{align}\label{claim3}
        \wass_2^2(\nu^{\sf LMC}_{k}, \pi) 
        \leqslant e^{-2mkh}\wass_2^2(\nu^{\sf LMC}_0, \pi) +
        \frac{(\Mav+m)hp}{2m}.
    \end{align}

[Gradient-step lemma]\label{lem:basic-gd}
    If the function $f$ is $m$-strongly convex, then for
    every $\btheta,\by\in\mathbb R^p$ and every $h>0$, we have
    \begin{align}
        \|\btheta-h\nabla f(\btheta)-\by\|_2^2
        \leqslant
        (1-mh)\|\btheta-\by\|_2^2
        + 2h\big(f(\by)-f(\btheta)\big)
        + h^2\|\nabla f(\btheta)\|_2^2.
        \label{eq:basic-gd}
    \end{align}
